import numpy as np
def purity(rho): return np.real(np.trace(rho@rho))
def linear_entropy(rho): return 1 - purity(rho)
rho = np.diag([0.7, 0.3])
print(purity(rho), linear_entropy(rho))  # 0.58, 0.42

import numpy as np
def is_ppt(rho, dA, dB):
    r = rho.reshape(dA,dB,dA,dB).transpose(0,3,2,1).reshape(dA*dB,dA*dB)
    return np.all(np.linalg.eigvalsh(r) > -1e-10)
bell = np.array([1,0,0,1])/np.sqrt(2)
print(is_ppt(np.outer(bell,bell),2,2))  # False -> entangled

import numpy as np
def trace_distance(rho,sigma):
    ev=np.linalg.eigvalsh(rho-sigma)
    return 0.5*np.sum(np.abs(ev))
rho=np.diag([1,0]); sigma=np.diag([0,1])
print(trace_distance(rho,sigma))  # 1.0 -> perfectly distinguishable

import numpy as np
def vN(rho):
    ev=np.linalg.eigvalsh(rho); ev=ev[ev>1e-12]
    return -np.sum(ev*np.log2(ev))
def mutual_info(rhoAB,rhoA,rhoB):
    return vN(rhoA)+vN(rhoB)-vN(rhoAB)
bell=np.array([1,0,0,1])/np.sqrt(2)
rho=np.outer(bell,bell)
print(mutual_info(rho, 0.5*np.eye(2), 0.5*np.eye(2)))  # 2 bits

import numpy as np
I=np.eye(2);X=np.array([[0,1],[1,0]])
Y=np.array([[0,-1j],[1j,0]]);Z=np.array([[1,0],[0,-1]])
def rebuild(ex,ey,ez):
    return 0.5*(I + ex*X + ey*Y + ez*Z)
print(np.round(rebuild(0,0,1),3))  # |0><0|
